"""Credit-hold sweep migrated from Meridian CRM 4.2."""

from decimal import Decimal
from typing import Any


_ZERO = Decimal("0")
_RELEASE_RATIO = Decimal("8") / Decimal("10")


def _number(value: Any) -> Decimal:
    """Apply legacy NVL/empty-string numeric coercion using exact decimals."""
    if value is None or value == "":
        return _ZERO
    if isinstance(value, Decimal):
        return value
    if isinstance(value, float):
        return Decimal(str(value))
    return Decimal(value)


def sweep(
    accounts: list[dict],
    orders: list[dict],
) -> tuple[list[dict], list]:
    """Apply the legacy nightly credit-hold rules without mutating inputs."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    exposure_by_account: dict[Any, Decimal] = {}
    for order in orders:
        if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") != "I":
            continue

        account_id = order.get("ACCT_ID")
        exposure_by_account[account_id] = (
            exposure_by_account.get(account_id, _ZERO)
            + _number(order.get("TOT_AMT", ""))
        )

    eligible_indices = [
        index
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible_indices.sort(key=lambda index: new_accounts[index].get("ACCT_ID"))

    for index in eligible_indices:
        account = new_accounts[index]
        account_id = account.get("ACCT_ID")
        exposure = exposure_by_account.get(account_id, _ZERO)
        credit_limit = _number(account.get("CRED_LIMIT", ""))

        if exposure > credit_limit and account.get("CRED_HOLD", "") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", account_id))

        if (
            exposure <= credit_limit * _RELEASE_RATIO
            and account.get("CRED_HOLD", "") == "Y"
        ):
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", account_id))

    return new_accounts, audits
